define('DOING_CRON',true);require __DIR__.'/m0/bootstrap.php';require_once EIPSI_FORMS_PLUGIN_DIR.'includes/study-engine/builder.php';require_once EIPSI_FORMS_PLUGIN_DIR.'includes/study-engine/privacy.php';require __DIR__.'/study-engine/cross-sectional/support.php';require __DIR__.'/study-engine/persistence/support.php';require __DIR__.'/study-engine/longitudinal/support.php';
use EIPSI\StudyEngine\Management as M;use EIPSI\StudyEngine\Builder as B;use EIPSI\StudyEngine\Persistence as P;
$tests=0;$failures=0;$owned=array();$svc=new B\Service(pf_db());$GLOBALS['pf_now']=gmdate('Y-m-d\TH:i:s\Z');wp_set_current_user(1);
function mg_test($name,$fn){global $tests,$failures;$tests++;try{$fn();echo 'PASS '.$name."\n";}catch(Throwable $e){$failures++;echo 'FAIL '.$name.': '.$e->getMessage().' '.$e->getFile().':'.$e->getLine()."\n";}}
function mg_study(){global $owned;$p=pf_publish(null,array('verification_policy'=>'ALLOW_UNVERIFIED'));$owned[]=$p['definition']['study']['logical_id'];return $p;}
function mg_query($p){return new M\Query($p['definition']['study']['logical_id']);}
function mg_finish($p,$email='mg@example.test'){$f=pf_enroll($p,$email);return pf_runtime()->handle($p['public'],$f['token'],pe_request($f,'submit',array('R_q1'=>'=not a spreadsheet formula')));}
function mg_job($x,$f=array(),$kind='responses'){$j=$x->create($f,$kind,'EXPORT_'.bin2hex(random_bytes(8)));while(in_array($j['state'],array('PENDING','RUNNING'),true))$j=$x->step($j['id']);return $j;}
try{
mg_test('Management additive schema exists and converges migration',function(){foreach(array_keys(M\Schema::definitions()) as $slug){$r=EIPSI_Schema_Inspector::inspect($slug);pe_assert($r['exists']&&!$r['issues'],$slug);}pe_assert((int)get_option('eipsi_migration_version')===EIPSI_Migration_Runner::LATEST_VERSION);});
$p=mg_study();$f=mg_finish($p);$q=mg_query($p);$x=new M\Exports($q);
mg_test('Summary distinguishes participation opportunity and scientific completion',function()use($q){$r=$q->summary(array());pe_assert($r['counts']['participations']===1&&$r['counts']['completed']===1);pe_assert($r['opportunities']['COMPLETED']===1);pe_assert($r['response_rate']['denominator']===1);});
mg_test('Administrative consultation never mutates science queue or sends mail',function()use($q,$f){$id=$f['access']['execution_id'];$before=pf_db()->row(pf_db()->prepare('SELECT checkpoint_hash,revision,updated_at FROM '.pf_db()->table('study_executions').' WHERE id=%s',$id));$mail=count($GLOBALS['m0_mail']??array());$q->summary(array());$q->participants(array());$q->opportunities(array());$q->communications(array());$q->audit(array());$q->diagnosis(array());pe_equal($before,pf_db()->row(pf_db()->prepare('SELECT checkpoint_hash,revision,updated_at FROM '.pf_db()->table('study_executions').' WHERE id=%s',$id)));pe_assert(count($GLOBALS['m0_mail']??array())===$mail);$read=B\Admin::handle(array('operation'=>'manage','study_id'=>$q->study,'section'=>'summary','filters'=>array()),wp_create_nonce('eipsi_study_builder'));pe_assert($read['counts']['participations']===1);});
mg_test('Every management entry requires authorization and CSRF',function()use($q,$p){wp_set_current_user(0);try{pe_reject(function()use($p){mg_query($p);},'BUILDER_FORBIDDEN');}finally{wp_set_current_user(1);}pe_reject(function()use($q){B\Admin::handle(array('operation'=>'manage','study_id'=>$q->study),'bad');},'BUILDER_CSRF');});
mg_test('Filters reject SQL-like cursor unknown fields invalid dates and types',function(){foreach(array(array('cycle'=>'1'),array('from'=>'2026-99-01'),array('cursor'=>"x' OR 1=1"),array('sql'=>'SELECT'),array('include_partials'=>1),array('limit'=>1001)) as $f)pe_reject(function()use($f){M\Query::filters($f);},'MANAGEMENT_FILTER_INVALID');});
mg_test('Participation and identity details cannot cross study boundaries',function()use($q,$f){$other=mg_study();$oq=mg_query($other);pe_reject(function()use($oq,$f){$oq->identity($f['access']['execution_id']);},'MANAGEMENT_PARTICIPATION_NOT_FOUND');$r=$q->identity($f['access']['execution_id']);pe_assert($r['identity']['email']==='mg@example.test');$a=$q->audit(array('execution'=>$f['access']['execution_id']));pe_assert(in_array('IDENTITY_VIEW',array_column($a['items'],'action'),true));});
mg_test('Export job is private resumable idempotent and has manifest',function()use($x){$j=$x->create(array(),'responses','MANAGEMENT_IDEMPOTENT');$again=$x->create(array(),'responses','MANAGEMENT_IDEMPOTENT');pe_assert($j['id']===$again['id']);$j=$x->step($j['id']);pe_assert($j['state']==='READY'&&$j['manifest']['rows']===1);$file=$x->download($j['id'],'json');$d=json_decode($file['content'],true);pe_assert($d['rows'][0]['value']==='=not a spreadsheet formula');pe_assert($d['manifest']['columns']===M\Exports::COLUMNS);$csv=$x->download($j['id'],'csv');pe_assert(strpos($csv['content'],"'=not a spreadsheet formula")!==false);});
mg_test('Different export parameters cannot reuse an idempotency key',function()use($x){pe_reject(function()use($x){$x->create(array(),'progress','MANAGEMENT_IDEMPOTENT');},'EXPORT_REQUEST_REUSED');});
mg_test('Export artifacts cannot cross study or actor scope',function()use($x){$j=mg_job($x);$other=mg_study();$ox=new M\Exports(mg_query($other));pe_reject(function()use($ox,$j){$ox->download($j['id'],'json');},'MANAGEMENT_EXPORT_NOT_FOUND');});
mg_test('Dataset changes invalidate generation instead of returning partial snapshot',function()use($q,$x,$f){$j=$x->create(array(),'responses','CHANGE_'.bin2hex(random_bytes(4)));pf_db()->transactional(function()use($f){pf_db()->query(pf_db()->prepare('UPDATE '.pf_db()->table('study_executions').' SET revision=revision+1 WHERE id=%s',$f['access']['execution_id']));});$j=$x->step($j['id']);pe_assert($j['state']==='INVALIDATED');});
mg_test('Progress export and diagnosis contain measured states not fabricated health',function()use($x,$q){$j=mg_job($x,array(),'progress');pe_assert($j['state']==='READY');$rows=json_decode($x->download($j['id'],'json')['content'],true)['rows'];pe_assert($rows[0]['state']==='COMPLETED');$d=$q->diagnosis(array());pe_assert(in_array('NOT_MEASURED',array_column($d['checks'],'status'),true));});
mg_test('Exclusion immediately purges pending analytical artifacts and excludes counters',function()use($p,$f,$q,$x){$j=mg_job($x);pf_db()->transactional(function()use($f){$id=$f['access']['execution_id'];$e=(new P\StudyExecutionRepository(pf_db()))->find($id);pf_db()->update('study_executions',array('data_policy'=>'DO_NOT_USE'),pf_db()->prepare('id=%s',$id));});pe_reject(function()use($x,$j){$x->download($j['id'],'json');},'EXPORT_UNAVAILABLE_OR_CHANGED');pe_assert($q->summary(array())['opportunities']['COMPLETED']===0&&$q->summary(array())['counts']['completed']===0);$empty=mg_job($x);pe_assert($empty['manifest']['rows']===0);});
mg_test('Admin logs cannot persist email tokens responses or seeds',function()use($q){M\Audit::record($q->study,'TEST_SAFE',null,null,array('token'=>'SECRET','email'=>'private@example.test','answers'=>array('PII'),'seed'=>'SECRET','result'=>'OK'));$r=$q->audit(array());$json=json_encode($r['items']);pe_assert(strpos($json,'SECRET')===false&&strpos($json,'private@example.test')===false);});
mg_test('Pagination is stable across participations and opportunities',function()use($p,$q){for($i=0;$i<4;$i++)pf_enroll($p,'page'.$i.'@example.test');$a=$q->participants(array('limit'=>2));$b=$q->participants(array('limit'=>2,'cursor'=>$a['next']));pe_assert(count($a['items'])===2&&count($b['items'])===2&&!array_intersect(array_column($a['items'],'id'),array_column($b['items'],'id')));$o=$q->opportunities(array('limit'=>2));pe_assert(count($o['items'])===2&&$o['next']!==null);});
