mg_test('Native management uses pinned definitions and generated bindings',function()use(&$nq,&$nx,&$nativeOwner,&$nativeDef,&$nativeFrame,&$nativeId,&$nativeStudy){
 global $svc,$owned;require_once EIPSI_FORMS_PLUGIN_DIR.'includes/study-engine/runtime/NativeBridge.php';$nativeOwner=new EIPSI\AssessmentEditor\Runtime\Owner();$nativeOwner->store->install();$nativeDef=json_decode(file_get_contents(__DIR__.'/assessment-editor/authoring-fixture.json'),true);$nativeDef['id']='AE_MG_'.bin2hex(random_bytes(8));$nativeDef['elements']=array_values(array_filter($nativeDef['elements'],static function($e){return in_array($e['type'],array('text','likert','matrix','vas'),true);}));foreach($nativeDef['elements'] as &$e){foreach(array('label_html','helper_html','footer_html') as $html)if(isset($e['properties'][$html]))$e['properties'][$html]=preg_replace('/<img\b[^>]*>/i','',$e['properties'][$html]);$e['properties']['required']=false;if($e['type']==='matrix')foreach($e['properties']['matrix_rows'] as &$r)$r['required']=false;unset($r);}unset($e);$nativeDef=EIPSI\AssessmentEditor\Definition::validate($nativeDef);$nativeDef['flow']['pages']=array();$nativeDef['flow']['metadata_profile']='basic';$nativeDef['flow']['allow_discard']=true;$nativeDef=EIPSI\AssessmentEditor\Definition::validate($nativeDef);EIPSI\AssessmentEditor\Repository::save($nativeDef,0);$version=$nativeOwner->publish($nativeDef['id'],1);
 putenv('EIPSI_STUDY_ENGINE_KEYRING='.json_encode(array('current'=>'MG','keys'=>array('MG'=>str_repeat('51',32)))));$nativeStudy=$svc->create(array('name'=>'Gestión Native'),'MG_NATIVE_'.bin2hex(random_bytes(8)));$owned[]=$nativeStudy['study_id'];$d=$nativeStudy['definition'];$node=B\Draft::block('E_NATIVE',$d['id'],$d['root_block_ids'][0],'MICRO',0);$node['schedule']=B\Draft::schedule();$node['metadata']['native_version_id']=$version['version_id'];$d['nodes'][]=$node;$nativeStudy=$svc->save($nativeStudy['id'],0,'MG_NATIVE_SAVE',$d);$nativeStudy=$svc->publish($nativeStudy['id'],$nativeStudy['revision'],array());$nativeStudy=$svc->activate($nativeStudy['id'],$nativeStudy['revision'],'OPEN');$runtime=new EIPSI\StudyEngine\Runtime\CrossSectionalRuntime(pf_db(),new P\SeedVault(array('MG'=>hex2bin(str_repeat('51',32))),'MG'));$frame=$runtime->handle($nativeStudy['definition']['study']['public_id']);$_COOKIE[EIPSI\StudyEngine\Runtime\AnonymousAccess::cookieName($frame['study']['public_id'])]=$frame['token'];$offer=EIPSI\StudyEngine\Runtime\NativeBridge::offer($frame);$nativeId=$offer['execution_id'];$nativeFrame=$nativeOwner->view($nativeId);$nq=new M\Query($nativeStudy['study_id']);$nx=new M\Exports($nq);$a=$nq->attempt($nativeId);pe_assert($a['title']===$nativeDef['title']&&$a['version_id']===$version['version_id']);pe_assert(count($nq->attempts(array())['items'])===1);
});
mg_test('Native dictionary exports all configured variables before any answer',function()use(&$nq,&$nx,&$nativeDef){$j=mg_job($nx,array(),'dictionary');pe_assert($j['state']==='READY');$rows=json_decode($nx->download($j['id'],'json')['content'],true)['rows'];pe_assert(count($rows)===count(M\Query::dictionary($nativeDef)));pe_assert(in_array('vas',array_column($rows,'type'),true));});
mg_test('Native submission is numerically typed and audited without copying answers',function()use(&$nq,&$nativeOwner,&$nativeDef,&$nativeFrame,&$nativeId){
 $meta=array('contract'=>'NATIVE_PROCESS_V1','assessment_id'=>$nativeDef['id'],'definition_ref'=>array(),'started_at'=>1000,'completed_at'=>null,'duration'=>0,'status'=>'active','recovery_used'=>false,'recovery_count'=>0,'pages'=>array(),'items'=>array(),'events'=>array(),'dropped_events'=>0);$request=array('action'=>'open','command_id'=>'MG_OPEN','revision'=>$nativeFrame['revision'],'version_id'=>$nativeFrame['version_id'],'csrf'=>$nativeFrame['csrf'],'answers'=>array(),'touched'=>array(),'metadata'=>$meta);$nativeFrame=$nativeOwner->command($nativeId,$request);$request['action']='submit';$request['command_id']='MG_SUBMIT';$request['revision']=$nativeFrame['revision'];foreach($nativeDef['elements'] as $e){if($e['type']==='matrix')foreach($e['properties']['matrix_rows'] as $r)$request['answers'][$r['response_key']]=$e['options'][0]['id'];elseif($e['type']==='likert')$request['answers'][$e['response_key']]=$e['options'][0]['id'];elseif($e['type']==='vas'){$request['answers'][$e['response_key']]=$e['properties']['min'];$request['touched'][$e['response_key']]=true;}else $request['answers'][$e['response_key']]='Respuesta confidencial';}$nativeFrame=$nativeOwner->command($nativeId,$request);$a=$nq->attempt($nativeId);$numeric=0;foreach($a['rows'] as $row)if(is_int($row['value'])||is_float($row['value']))$numeric++;pe_assert($numeric>=3);$audit=$nq->audit(array());pe_assert(in_array('NATIVE_SUBMIT',array_column($audit['items'],'action'),true));pe_assert(strpos(json_encode($audit),'Respuesta confidencial')===false);
});
mg_test('Native exports retain attempt context typed values fixed columns and dictionary',function()use(&$nq,&$nx){$j=mg_job($nx);pe_assert($j['state']==='READY'&&$j['manifest']['rows']>=4);$rows=json_decode($nx->download($j['id'],'json')['content'],true)['rows'];foreach($rows as $r)pe_assert($r['native_version_id']!==null&&$r['attempt_id']!==null&&!array_diff(M\Exports::COLUMNS,array_keys($r))&&$r['response_status']==='VALUE_RECORDED');$s=$nq->summary(array());pe_assert($s['responded_opportunities']===1&&$s['attempts']['completed']===1);});
