mg_test('Discard purges artifacts and removes the response without changing prior study decisions',function()use(&$nq,&$nx,&$nativeOwner,&$nativeFrame,&$nativeId,&$nativeDef){$j=mg_job($nx);$meta=array('contract'=>'NATIVE_PROCESS_V1','assessment_id'=>$nativeDef['id'],'definition_ref'=>array(),'started_at'=>1000,'completed_at'=>null,'duration'=>0,'status'=>'active','recovery_used'=>false,'recovery_count'=>0,'pages'=>array(),'items'=>array(),'events'=>array(),'dropped_events'=>0);$nativeOwner->command($nativeId,array('action'=>'discard','command_id'=>'MG_DISCARD','revision'=>$nativeFrame['revision'],'version_id'=>$nativeFrame['version_id'],'csrf'=>$nativeFrame['csrf'],'answers'=>array(),'touched'=>array(),'metadata'=>$meta));$row=pf_db()->row(pf_db()->prepare('SELECT payload_json,state FROM '.pf_db()->table('management_exports').' WHERE id=%s',$j['id']));pe_assert($row['payload_json']===null&&$row['state']==='INVALIDATED');pe_assert($nq->summary(array())['responded_opportunities']===0);pe_assert(!$nq->attempt($nativeId)['rows']);});
mg_test('Actual concurrent withdrawal blocks download then erases export payloads',function(){ $p=mg_study();$f=mg_finish($p,'withdraw-mg@example.test');$q=mg_query($p);$x=new M\Exports($q);$j=mg_job($x);$id=$f['access']['execution_id'];$e=(new P\StudyExecutionRepository(pf_db()))->find($id);$access=EIPSI\StudyEngine\Privacy\AccessContext::session(pf_db(),$p['public'],$f['token'],pf_clock());require __DIR__.'/study-engine/management/race.php';$worker=null;$observer=mg_download_observer($q->study,$j['id'],$worker);try{pf_owner($observer)->withdrawExecution($id,'DO_NOT_USE','MG_WITHDRAW',(int)$e['revision'],$access);}finally{mg_download_result($worker);}$r=pf_db()->row(pf_db()->prepare('SELECT state,payload_json FROM '.pf_db()->table('management_exports').' WHERE id=%s',$j['id']));pe_assert($r['state']==='INVALIDATED'&&$r['payload_json']===null);});
mg_test('Finalization invalidates downloads and distinguishes administrative closure',function()use(&$nativeStudy,&$nq,&$nx){global $svc;$j=mg_job($nx,array(),'progress');$current=$svc->load($nativeStudy['id']);$svc->changeStudyState($nativeStudy['id'],$current['lifecycle']['revision'],'FINALIZED',true,'MG_FINALIZE');pe_assert($nq->context()['state']==='FINALIZED');pe_reject(function()use($nx,$j){$nx->download($j['id'],'json');},'EXPORT_UNAVAILABLE_OR_CHANGED');});
}finally{wp_set_current_user(1);foreach($owned as $study)try{$svc->deleteStudy($study,'ELIMINAR '.$study);}catch(Throwable $e){echo 'cleanup '.$e->getMessage()."\n";}}
echo "$tests tests, $failures failures\n";exit($failures?1:0);
